# [doc = " A time zone aware instant in time."] # [doc = ""] # [doc = " A `Zoned` value can be thought of as the combination of following types,"] # [doc = " all rolled into one:"] # [doc = ""] # [doc = " * A [`Timestamp`] for indicating the precise instant in time."] # [doc = " * A [`DateTime`] for indicating the \"civil\" calendar date and clock time."] # [doc = " * A [`TimeZone`] for indicating how to apply time zone transitions while"] # [doc = " performing arithmetic."] # [doc = ""] # [doc = " In particular, a `Zoned` is specifically designed for dealing with"] # [doc = " datetimes in a time zone aware manner. Here are some highlights:"] # [doc = ""] # [doc = " * Arithmetic automatically adjusts for daylight saving time (DST), using"] # [doc = " the rules defined by [RFC 5545]."] # [doc = " * Creating new `Zoned` values from other `Zoned` values via [`Zoned::with`]"] # [doc = " by changing clock time (e.g., `02:30`) can do so without worrying that the"] # [doc = " time will be invalid due to DST transitions."] # [doc = " * An approximate superset of the [`DateTime`] API is offered on `Zoned`,"] # [doc = " but where each of its operations take time zone into account when"] # [doc = " appropriate. For example, [`DateTime::start_of_day`] always returns a"] # [doc = " datetime set to midnight, but [`Zoned::start_of_day`] returns the first"] # [doc = " instant of a day, which might not be midnight if there is a time zone"] # [doc = " transition at midnight."] # [doc = " * When using a `Zoned`, it is easy to switch between civil datetime (the"] # [doc = " day you see on the calendar and the time you see on the clock) and Unix"] # [doc = " time (a precise instant in time). Indeed, a `Zoned` can be losslessy"] # [doc = " converted to any other datetime type in this crate: [`Timestamp`],"] # [doc = " [`DateTime`], [`Date`] and [`Time`]."] # [doc = " * A `Zoned` value can be losslessly serialized and deserialized, via"] # [doc = " [serde], by adhering to [RFC 8536]. An example of a serialized zoned"] # [doc = " datetime is `2024-07-04T08:39:00-04:00[America/New_York]`."] # [doc = " * Since a `Zoned` stores a [`TimeZone`] itself, multiple time zone aware"] # [doc = " operations can be chained together without repeatedly specifying the time"] # [doc = " zone."] # [doc = ""] # [doc = " [RFC 5545]: https://datatracker.ietf.org/doc/html/rfc5545"] # [doc = " [RFC 8536]: https://datatracker.ietf.org/doc/html/rfc8536"] # [doc = " [serde]: https://serde.rs/"] # [doc = ""] # [doc = " # Parsing and printing"] # [doc = ""] # [doc = " The `Zoned` type provides convenient trait implementations of"] # [doc = " [`std::str::FromStr`] and [`std::fmt::Display`]:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::Zoned;"] # [doc = ""] # [doc = " let zdt: Zoned = \"2024-06-19 15:22[America/New_York]\".parse()?;"] # [doc = " // Notice that the second component and the offset have both been added."] # [doc = " assert_eq!(zdt.to_string(), \"2024-06-19T15:22:00-04:00[America/New_York]\");"] # [doc = ""] # [doc = " // While in the above case the datetime is unambiguous, in some cases, it"] # [doc = " // can be ambiguous. In these cases, an offset is required to correctly"] # [doc = " // roundtrip a zoned datetime. For example, on 2024-11-03 in New York, the"] # [doc = " // 1 o'clock hour was repeated twice, corresponding to the end of daylight"] # [doc = " // saving time."] # [doc = " //"] # [doc = " // So because of the ambiguity, this time could be in offset -04 (the first"] # [doc = " // time 1 o'clock is on the clock) or it could be -05 (the second time"] # [doc = " // 1 o'clock is on the clock, corresponding to the end of DST)."] # [doc = " //"] # [doc = " // By default, parsing uses a \"compatible\" strategy for resolving all cases"] # [doc = " // of ambiguity: in forward transitions (gaps), the later time is selected."] # [doc = " // And in backward transitions (folds), the earlier time is selected."] # [doc = " let zdt: Zoned = \"2024-11-03 01:30[America/New_York]\".parse()?;"] # [doc = " // As we can see, since this was a fold, the earlier time was selected"] # [doc = " // because the -04 offset is the first time 1 o'clock appears on the clock."] # [doc = " assert_eq!(zdt.to_string(), \"2024-11-03T01:30:00-04:00[America/New_York]\");"] # [doc = " // But if we changed the offset and re-serialized, the only thing that"] # [doc = " // changes is, indeed, the offset. This demonstrates that the offset is"] # [doc = " // key to ensuring lossless serialization."] # [doc = " let zdt = zdt.with().offset(jiff::tz::offset(-5)).build()?;"] # [doc = " assert_eq!(zdt.to_string(), \"2024-11-03T01:30:00-05:00[America/New_York]\");"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " A `Zoned` can also be parsed from just a time zone aware date (but the"] # [doc = " time zone annotation is still required). In this case, the time is set to"] # [doc = " midnight:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::Zoned;"] # [doc = ""] # [doc = " let zdt: Zoned = \"2024-06-19[America/New_York]\".parse()?;"] # [doc = " assert_eq!(zdt.to_string(), \"2024-06-19T00:00:00-04:00[America/New_York]\");"] # [doc = " // ... although it isn't always midnight, in the case of a time zone"] # [doc = " // transition at midnight!"] # [doc = " let zdt: Zoned = \"2015-10-18[America/Sao_Paulo]\".parse()?;"] # [doc = " assert_eq!(zdt.to_string(), \"2015-10-18T01:00:00-02:00[America/Sao_Paulo]\");"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " For more information on the specific format supported, see the"] # [doc = " [`fmt::temporal`](crate::fmt::temporal) module documentation."] # [doc = ""] # [doc = " # Leap seconds"] # [doc = ""] # [doc = " Jiff does not support leap seconds. Jiff behaves as if they don't exist."] # [doc = " The only exception is that if one parses a datetime with a second component"] # [doc = " of `60`, then it is automatically constrained to `59`:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, Zoned};"] # [doc = ""] # [doc = " let zdt: Zoned = \"2016-12-31 23:59:60[Australia/Tasmania]\".parse()?;"] # [doc = " assert_eq!(zdt.datetime(), date(2016, 12, 31).at(23, 59, 59, 0));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Comparisons"] # [doc = ""] # [doc = " The `Zoned` type provides both `Eq` and `Ord` trait implementations to"] # [doc = " facilitate easy comparisons. When a zoned datetime `zdt1` occurs before a"] # [doc = " zoned datetime `zdt2`, then `zdt1 < zdt2`. For example:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::civil::date;"] # [doc = ""] # [doc = " let zdt1 = date(2024, 3, 11).at(1, 25, 15, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2025, 1, 31).at(0, 30, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " assert!(zdt1 < zdt2);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Note that `Zoned` comparisons only consider the precise instant in time."] # [doc = " The civil datetime or even the time zone are completely ignored. So it's"] # [doc = " possible for a zoned datetime to be less than another even if it's civil"] # [doc = " datetime is bigger:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::civil::date;"] # [doc = ""] # [doc = " let zdt1 = date(2024, 7, 4).at(12, 0, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2024, 7, 4).at(11, 0, 0, 0).in_tz(\"America/Los_Angeles\")?;"] # [doc = " assert!(zdt1 < zdt2);"] # [doc = " // But if we only compare civil datetime, the result is flipped:"] # [doc = " assert!(zdt1.datetime() > zdt2.datetime());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " The same applies for equality as well. Two `Zoned` values are equal, even"] # [doc = " if they have different time zones, when the instant in time is identical:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::civil::date;"] # [doc = ""] # [doc = " let zdt1 = date(2024, 7, 4).at(12, 0, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2024, 7, 4).at(9, 0, 0, 0).in_tz(\"America/Los_Angeles\")?;"] # [doc = " assert_eq!(zdt1, zdt2);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " (Note that this is different from"] # [doc = " [Temporal's `ZonedDateTime.equals`][temporal-equals] comparison, which will"] # [doc = " take time zone into account for equality. This is because `Eq` and `Ord`"] # [doc = " trait implementations must be consistent in Rust. If you need Temporal's"] # [doc = " behavior, then use `zdt1 == zdt2 && zdt1.time_zone() == zdt2.time_zone()`.)"] # [doc = ""] # [doc = " [temporal-equals]: https://tc39.es/proposal-temporal/docs/zoneddatetime.html#equals"] # [doc = ""] # [doc = " # Arithmetic"] # [doc = ""] # [doc = " This type provides routines for adding and subtracting spans of time, as"] # [doc = " well as computing the span of time between two `Zoned` values. These"] # [doc = " operations take time zones into account."] # [doc = ""] # [doc = " For adding or subtracting spans of time, one can use any of the following"] # [doc = " routines:"] # [doc = ""] # [doc = " * [`Zoned::checked_add`] or [`Zoned::checked_sub`] for checked"] # [doc = " arithmetic."] # [doc = " * [`Zoned::saturating_add`] or [`Zoned::saturating_sub`] for"] # [doc = " saturating arithmetic."] # [doc = ""] # [doc = " Additionally, checked arithmetic is available via the `Add` and `Sub`"] # [doc = " trait implementations. When the result overflows, a panic occurs."] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, ToSpan};"] # [doc = ""] # [doc = " let start = date(2024, 2, 25).at(15, 45, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " // `Zoned` doesn't implement `Copy`, so you'll want to use `&start` instead"] # [doc = " // of `start` if you want to keep using it after arithmetic."] # [doc = " let one_week_later = start + 1.weeks();"] # [doc = " assert_eq!(one_week_later.datetime(), date(2024, 3, 3).at(15, 45, 0, 0));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " One can compute the span of time between two zoned datetimes using either"] # [doc = " [`Zoned::until`] or [`Zoned::since`]. It's also possible to subtract"] # [doc = " two `Zoned` values directly via a `Sub` trait implementation:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, ToSpan};"] # [doc = ""] # [doc = " let zdt1 = date(2024, 5, 3).at(23, 30, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2024, 2, 25).at(7, 0, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " assert_eq!(zdt1 - zdt2, 1647.hours().minutes(30).fieldwise());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " The `until` and `since` APIs are polymorphic and allow re-balancing and"] # [doc = " rounding the span returned. For example, the default largest unit is hours"] # [doc = " (as exemplified above), but we can ask for bigger units:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, ToSpan, Unit};"] # [doc = ""] # [doc = " let zdt1 = date(2024, 5, 3).at(23, 30, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2024, 2, 25).at(7, 0, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " assert_eq!("] # [doc = "     zdt1.since((Unit::Year, &zdt2))?,"] # [doc = "     2.months().days(7).hours(16).minutes(30).fieldwise(),"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Or even round the span returned:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, RoundMode, ToSpan, Unit, ZonedDifference};"] # [doc = ""] # [doc = " let zdt1 = date(2024, 5, 3).at(23, 30, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " let zdt2 = date(2024, 2, 25).at(7, 0, 0, 0).in_tz(\"America/New_York\")?;"] # [doc = " assert_eq!("] # [doc = "     zdt1.since("] # [doc = "         ZonedDifference::new(&zdt2)"] # [doc = "             .smallest(Unit::Day)"] # [doc = "             .largest(Unit::Year),"] # [doc = "     )?,"] # [doc = "     2.months().days(7).fieldwise(),"] # [doc = " );"] # [doc = " // `ZonedDifference` uses truncation as a rounding mode by default,"] # [doc = " // but you can set the rounding mode to break ties away from zero:"] # [doc = " assert_eq!("] # [doc = "     zdt1.since("] # [doc = "         ZonedDifference::new(&zdt2)"] # [doc = "             .smallest(Unit::Day)"] # [doc = "             .largest(Unit::Year)"] # [doc = "             .mode(RoundMode::HalfExpand),"] # [doc = "     )?,"] # [doc = "     // Rounds up to 8 days."] # [doc = "     2.months().days(8).fieldwise(),"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Rounding"] # [doc = ""] # [doc = " A `Zoned` can be rounded based on a [`ZonedRound`] configuration of"] # [doc = " smallest units, rounding increment and rounding mode. Here's an example"] # [doc = " showing how to round to the nearest third hour:"] # [doc = ""] # [doc = " ```"] # [doc = " use jiff::{civil::date, Unit, ZonedRound};"] # [doc = ""] # [doc = " let zdt = date(2024, 6, 19)"] # [doc = "     .at(16, 27, 29, 999_999_999)"] # [doc = "     .in_tz(\"America/New_York\")?;"] # [doc = " assert_eq!("] # [doc = "     zdt.round(ZonedRound::new().smallest(Unit::Hour).increment(3))?,"] # [doc = "     date(2024, 6, 19).at(15, 0, 0, 0).in_tz(\"America/New_York\")?,"] # [doc = " );"] # [doc = " // Or alternatively, make use of the `From<(Unit, i64)> for ZonedRound`"] # [doc = " // trait implementation:"] # [doc = " assert_eq!("] # [doc = "     zdt.round((Unit::Hour, 3))?,"] # [doc = "     date(2024, 6, 19).at(15, 0, 0, 0).in_tz(\"America/New_York\")?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " See [`Zoned::round`] for more details."] # [derive (Clone)] pub struct Zoned { inner : ZonedInner , }
